\label{lem:convergence_rate_lower_bound_by_sum_of_stepsizes}
For any $\bm{\eta}\in(0,\infty)^{\mathbb{N}}$,
\begin{enumerate}[label=(\roman*)]
    \item we have $Q_n(\bm{\eta}) \geq \frac{1}{4(1+2\eta_{1:n})}$ for all $n\in\mathbb{N}$.
    \item If $Q_n(\bm{\eta}) = o(n^{-1})$, then $\limsup_{n\to\infty}\eta_n = \infty$.
\end{enumerate}

The lower bound in \Cref{lem:convergence_rate_lower_bound_by_sum_of_stepsizes} (i) may remind readers about the two lower bounds, $R_n(\bm{\eta})\geq\frac{1}{1+2\eta_{1:n}}$ and $G_n(\bm{\eta})\geq\frac{1}{1+2\eta_{1:n}}$, both of which can be derived from the Huber function:
\begin{equation}\label{eq:huber}
	f(x) = \begin{cases}
		\frac{1}{2}x^2 &\text{if } \abs{x}\leq\delta, \\
		\delta\abs{x} - \frac{1}{2}\delta^2 &\text{if }\abs{x}\geq\delta,
	\end{cases}
\end{equation}
with $x_1=1$ and some properly chosen $\delta$.
Although both bounds are commonly used in the literature (see, e.g., \cite{drori:2014,grimmer:2025a,taylor:2017a}), we do not use them in our proof.
The reason is that they only improve  \Cref{lem:convergence_rate_lower_bound_by_sum_of_stepsizes} (i) by a constant factor, so incorporating them will not improve the order of our results.

\begin{align*}
	\eta_{1:n}
	&= \int_{(0,\infty)} \eta \, \mathrm{d} \mu_n(\eta)\\
	&= \int_0^\infty \mu_n\left( \{ \eta\in(0,\infty): \eta > t \} \right)\, \mathrm{d} t \\
	&= \int_0^\infty N_n(t)\,\mathrm{d} t \\
	&= \int_0^{M_n} N_n(t)\,\mathrm{d} t,
\end{align*}

We introduce the asymmetric Huber functions, which are parameterized by $\varepsilon>0$ and $\delta>0$ and are defined as
\begin{equation}\label{eq:asymmetric_huber}
	f(x) \coloneqq \begin{cases}
		\delta\abs{x} - \frac{ \delta^2 }{2} &\text{if }x\geq\delta, \\
		\frac{1}{2}x^2 &\text{if }-\varepsilon \leq x \leq \delta, \\
		\varepsilon\abs{x} - \frac{ \varepsilon^2 }{2} &\text{if }x\leq-\varepsilon.
	\end{cases}
\end{equation}

\label{lem:asymmetric_huber}
For any $\bm{\eta}\in(0,\infty)^{\mathbb{N}}$, any $n\in\mathbb{N}$, and any $m\in[n]$ such that $\eta_m > 1$, we have
\begin{equation}\label{eq:asymmetric_huber_part_i}
\begin{split}
	R_n(\bm{\eta}) &\geq \frac{ (\eta_m-1)^2 }{ ( 1 + \eta_{1:m-1} )^2 ( 1 + 2 \eta_{m+1:n} ) }, \\
	G_n(\bm{\eta}) &\geq \frac{ (\eta_m-1)^2 }{ ( 1 + 2 \eta_{1:m-1} ) ( 1 + \eta_{m+1:n} )^2 }.
\end{split}
\end{equation}
In particular, we have for any $n\in\mathbb{N}$,
\begin{equation}\label{eq:asymmetric_huber_part_ii}
\begin{split}
	\eta_n &\leq 1 + (1 + \eta_{1:n-1})\sqrt{R_n(\bm{\eta})}, \\
	\eta_n &\leq 1 + \sqrt{1 + 2\eta_{1:n-1}}\sqrt{G_n(\bm{\eta})}.
\end{split}
\end{equation}

\begin{align*}
